import heapq


def order_tasks(deps):
    """Return a topological ordering of tasks.

    ``deps`` maps each task name to an iterable of prerequisite task names.
    At each step the lexicographically smallest currently-ready task is chosen.
    Duplicate prerequisites count once. Raises ``ValueError`` on a missing
    prerequisite or any cycle (including a self dependency). Empty input
    returns ``[]``. The input mapping and its iterables are not mutated.
    """
    # Snapshot the task names without mutating the input.
    tasks = list(deps.keys())

    # Deduplicate prerequisites per task and validate they all exist.
    prereqs = {}
    for task in tasks:
        seen = set()
        for p in deps[task]:
            if p not in deps:
                raise ValueError(
                    "missing prerequisite {!r} for task {!r}".format(p, task)
                )
            seen.add(p)
        prereqs[task] = seen

    # Build reverse edges (successors) and in-degrees from deduped prereqs.
    successors = {task: [] for task in tasks}
    indeg = {}
    for task in tasks:
        indeg[task] = len(prereqs[task])
        for p in prereqs[task]:
            successors[p].append(task)

    # Kahn's algorithm, always popping the lexicographically smallest ready task.
    heap = [task for task in tasks if indeg[task] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        task = heapq.heappop(heap)
        result.append(task)
        for nxt in successors[task]:
            indeg[nxt] -= 1
            if indeg[nxt] == 0:
                heapq.heappush(heap, nxt)

    if len(result) != len(tasks):
        raise ValueError("cycle detected among tasks")

    return result

import csv
import io
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def totals(csv_text):
    """Aggregate exact Decimal amounts per account from CSV text.

    The input must have headers ``account,amount``. Account names are
    trimmed; blank accounts and invalid/non-finite amounts raise ValueError.
    Amounts are summed exactly per account and only the final per-account
    total is rounded to two decimal places with ROUND_HALF_UP. Insertion
    order of accounts is preserved. Quoted accounts containing commas,
    CRLF line endings and header-only (empty) input are supported.
    """
    # newline='' lets the csv module handle CRLF and embedded newlines
    # inside quoted fields correctly.
    reader = csv.reader(io.StringIO(csv_text, newline=''))

    # Consume the header row (account,amount). Header-only input yields
    # no data rows and therefore an empty result.
    next(reader, None)

    # Plain dict preserves insertion order (Python 3.7+).
    sums = {}
    for row in reader:
        if len(row) < 2:
            raise ValueError("row must contain account and amount fields")

        account = row[0].strip()
        if not account:
            raise ValueError("account must not be blank")

        raw_amount = row[1].strip()
        try:
            amount = Decimal(raw_amount)
        except InvalidOperation:
            raise ValueError("invalid amount: {!r}".format(raw_amount))

        if not amount.is_finite():
            raise ValueError("amount must be finite: {!r}".format(raw_amount))

        # Sum exact amounts; rounding happens only on the final total.
        if account in sums:
            sums[account] += amount
        else:
            sums[account] = amount

    return {
        account: total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        for account, total in sums.items()
    }

