import heapq


def order_tasks(deps):
    """Return a topological ordering of tasks given their prerequisites.

    ``deps`` maps each task name to an iterable of prerequisite task names.
    At each step the lexicographically smallest ready task is chosen.
    Duplicate prerequisites are ignored. Raises ValueError if a prerequisite
    is not itself a task (missing prerequisite) or if the graph has a cycle
    (including a self-dependency). The input mapping is never mutated.
    """
    if not deps:
        return []

    # Deduplicate prerequisites and validate that every prerequisite is a task.
    prereqs = {}
    for task, prereq_list in deps.items():
        unique = set(prereq_list)
        for p in unique:
            if p not in deps:
                raise ValueError(f"missing prerequisite {p!r} for task {task!r}")
        prereqs[task] = unique

    # Kahn's algorithm: in-degree = number of unique prerequisites;
    # dependents maps a task to the tasks that require it.
    indegree = {task: len(pres) for task, pres in prereqs.items()}
    dependents = {task: [] for task in deps}
    for task, pres in prereqs.items():
        for p in pres:
            dependents[p].append(task)

    # Min-heap keeps the ready set ordered lexicographically.
    ready = [task for task, deg in indegree.items() if deg == 0]
    heapq.heapify(ready)

    order = []
    while ready:
        task = heapq.heappop(ready)
        order.append(task)
        for nxt in dependents[task]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                heapq.heappush(ready, nxt)

    if len(order) != len(deps):
        raise ValueError("dependency cycle detected")

    return order

"""Aggregate CSV amounts per account using exact decimal arithmetic."""

import csv
import io
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

_TWO_PLACES = Decimal("0.01")
_ZERO = Decimal("0")


def totals(csv_text):
    """Sum ``account,amount`` rows and return per-account Decimal totals.

    The first non-empty CSV row is treated as the ``account,amount`` header
    and skipped. Account names are trimmed; blank accounts and invalid or
    non-finite Decimal amounts raise ``ValueError``. Per-account sums are
    accumulated exactly and only the final total is rounded to two decimal
    places with ROUND_HALF_UP. The returned dict preserves first-seen
    account order.
    """
    # newline='' on StringIO mirrors the documented csv.reader file-opening
    # mode so CRLF line endings and embedded newlines in quoted fields work.
    rows = list(csv.reader(io.StringIO(csv_text, newline="")))

    # Skip the header row (the first row that actually has content).
    for index, row in enumerate(rows):
        if any(field.strip() for field in row):
            rows = rows[index + 1:]
            break
    else:
        rows = []

    totals_by_account = {}
    for row in rows:
        if not row or all(not field.strip() for field in row):
            continue  # blank filler line
        if len(row) < 2:
            raise ValueError(f"malformed row (missing amount): {row!r}")

        account = row[0].strip()
        if not account:
            raise ValueError(f"blank account: {row!r}")

        raw_amount = row[1].strip()
        try:
            amount = Decimal(raw_amount)
        except InvalidOperation:
            raise ValueError(f"invalid amount: {raw_amount!r}")
        if not amount.is_finite():
            raise ValueError(f"non-finite amount: {raw_amount!r}")

        # Exact accumulation; rounding happens only on the final total.
        totals_by_account[account] = totals_by_account.get(account, _ZERO) + amount

    # dict(...) preserves insertion order (first-seen account order).
    return {
        account: total.quantize(_TWO_PLACES, rounding=ROUND_HALF_UP)
        for account, total in totals_by_account.items()
    }
